#include "drive_popup_view.hpp"
#include <new>
#include <cmath>
#include <cstdio>
namespace x2dui {
void DrivePopupView::release(void*p){auto*b=static_cast<Binding*>(p);auto*v=b->self;delete b;v->drop();}
bool DrivePopupView::bind(void*o,Event e,int i){auto*b=new(std::nothrow)Binding(this,i);if(!b)return false;retain();if(api.listen(api.context,o,e,event,b,release))return true;release(b);return false;}
void DrivePopupView::event(void*p,Event e,double){auto*b=static_cast<Binding*>(p);auto&v=*b->self;if(e==Event::Destroy){v.root=nullptr;v.alive=false;return;}if(!v.alive||v.closed||!v.interactive)return;if(e==Event::Click){if(b->index==-1)v.key(DriveKey::Close);else if(b->index==-2)v.key(DriveKey::Parameters);}}
void DrivePopupView::pressed(void*p){auto*b=static_cast<Binding*>(p);auto&v=*b->self;if(!v.alive||v.closed||!v.interactive)return;v.retain();auto previous=v.model;if(v.model.press(b->index)){bool ok=v.flush();if(v.alive&&!v.closed&&!ok)v.model=previous;}if(v.alive&&!v.closed){v.redraw();v.api.visible(v.api.context,v.root,true);}v.drop();}
// 关闭请求尚待原厂确认时保留模态遮罩；确认后由附件随 mainState 退出销毁。
// model.closed() 仍阻止重复提交，避免提前露出下层曝光控件。
bool DrivePopupView::flush(){DriveAction actions[16],a;unsigned n=0;while(n<16&&model.take(a))actions[n++]=a;if(!n)return true;retain();bool ok=dispatch&&dispatch(context,actions,n);drop();return ok;}
void DrivePopupView::key(DriveKey k){if(!alive||closed)return;retain();auto previous=model;switch(k){case DriveKey::Up:model.move(0,-1);break;case DriveKey::Down:model.move(0,1);break;case DriveKey::Left:model.move(-1,0);break;case DriveKey::Right:model.move(1,0);break;case DriveKey::Accept:model.select(true);break;case DriveKey::Parameters:model.enter();break;case DriveKey::Close:model.close();break;}bool ok=flush();if(alive&&!closed){if(!ok)model=previous;redraw();api.visible(api.context,root,true);}drop();}
bool DrivePopupView::redraw(){if(!alive||closed||!root)return false;
 DriveSummary data;retain();bool got=summary&&summary(context,model.choice(model.index()),data);bool live=alive&&!closed;drop();if(!live)return false;if(!got||data.count<0||data.count>10||!data.caption.valid())return false;
 bool same=rendered&&renderedIndex==model.index()&&data.count==renderedSummary.count&&data.caption==renderedSummary.caption;
 for(int i=0;i<data.count;i++){if(!data.labels[i].valid()||!data.values[i].valid())return false;same=same&&data.labels[i]==renderedSummary.labels[i]&&data.values[i]==renderedSummary.values[i];}
 if(same)return true;rendered=false;auto c=api.context;double sx=style.scaleX,sy=style.scaleY,s=style.scale,pw=902.4*sx,ph=681.6*sy,left=409.6*sx,top=43.2*sy,px=(width-pw)/2,hh=89.6*sy;
 if(pw>width||ph+top>height)return false;api.rect(c,root,0,0,width,height);api.rect(c,shade,0,0,width,height);api.rect(c,outside,0,0,width,height);api.rect(c,frame,px,top,pw,ph);api.rect(c,panel,2,2,pw-4,ph-4);api.rect(c,heading,0,0,left,hh);api.rect(c,divider,left,0,2,ph);api.rect(c,summaryHeading,left,0,pw-left,hh);api.text(c,heading,u"拍摄模式",32*s,1);api.text(c,summaryHeading,DrivePopup::label(model.choice(model.index())),32*s,1);
 double iconW=121.6*sx,iconH=76.8*sy,side=44.8*sx,itemW=left-2*side-iconW,itemH=139.2*sy;bool ok=true;
 for(int i=0;i<8;i++){bool visible=i<model.count(),enabled=visible&&model.selectable(i);api.visible(c,icons[i],visible);if(!visible)continue;auto choice=model.choice(i);api.rect(c,icons[i],side+(i%2)*itemW-(itemW-iconW)/2,99.2*sy+(i/2)*itemH,itemW,itemH);
  ok=stock_set_text(stock,icons[i],"source",DrivePopup::icon(choice,!enabled))&&stock_set_text(stock,icons[i],"text",DrivePopup::label(choice))&&stock_set_number(stock,icons[i],"highlightWidth",iconW)&&stock_set_number(stock,icons[i],"highlightHeight",iconH)&&stock_set_number(stock,icons[i],"textPixelSize",28.8*s)&&stock_set_number(stock,icons[i],"textTopMargin",3.2*sy)&&stock_set_number(stock,icons[i],"textSideMargin",0)&&stock_set_bool(stock,icons[i],"forceHighlight",i==model.index())&&stock_set_bool(stock,icons[i],"selectable",enabled)&&stock_set_bool(stock,icons[i],"touchEnabled",interactive&&enabled)&&ok;
  auto image=stock_get_object(stock,icons[i],"image");if(!image)return false;ok=stock_set_number(stock,image,"scaleFactor",DrivePopup::extension(choice)==ExtensionMode::None?1:.52)&&ok;
 }

 double rightWidth=pw-left,margin=22.4*sx,rowTop=107.2*sy,available=ph-rowTop-70*sy,rh=40*s,spacing=data.count>1?(available-data.count*rh)/(data.count-1):0;if(spacing<0)spacing=0;if(spacing>51.2*sy)spacing=51.2*sy;
 for(int i=0;i<10;i++){bool show=i<data.count;api.visible(c,rows[i],show);if(!show)continue;if(!data.labels[i].valid()||!data.values[i].valid())return false;api.rect(c,rows[i],left+margin,rowTop+i*(rh+spacing),rightWidth-2*margin,rh);ok=stock_set_text(stock,rows[i],"text",data.labels[i].c_str())&&stock_set_text(stock,rows[i],"valueText",data.values[i].c_str())&&stock_set_number(stock,rows[i],"pixelSize",rh)&&ok;}
 api.rect(c,caption,left+margin,ph-66*sy,rightWidth-2*margin,60*sy);api.text(c,caption,data.caption.c_str(),22*s,1);api.rect(c,summaryTouch,left,0,rightWidth,ph);api.enabled(c,summaryTouch,interactive&&model.can_settings(model.index()));if(ok){renderedSummary=static_cast<DriveSummary&&>(data);renderedIndex=model.index();rendered=true;}return ok;
}
bool DrivePopupView::update(DrivePermissions p,DriveChoice actual,ExtensionMode selected,const DriveStyle&s,double w,double h,bool touchEnabled){if(!alive||closed)return false;
 if(!std::isfinite(w)||!std::isfinite(h)||w<=0||h<=0||w>8192||h>8192||!std::isfinite(s.scale)||!std::isfinite(s.scaleX)||!std::isfinite(s.scaleY)||s.scale<=0||s.scaleX<=0||s.scaleY<=0||s.scale>4||s.scaleX>4||s.scaleY>4){api.visible(api.context,root,false);return false;}
 bool changed=!configured||actual!=priorActual||selected!=priorExtension||p.fullAuto!=priorPermissions.fullAuto||p.microFocusAdjust!=priorPermissions.microFocusAdjust||p.pixel400!=priorPermissions.pixel400||p.quarter!=priorPermissions.quarter||p.stack!=priorPermissions.stack||p.manual!=priorPermissions.manual;
 if(changed){model.configure(p,actual,selected);priorActual=actual;priorExtension=selected;priorPermissions=p;configured=true;}
 bool visualChanged=changed||width!=w||height!=h||interactive!=touchEnabled||style.scale!=s.scale||style.scaleX!=s.scaleX||style.scaleY!=s.scaleY||style.background!=s.background||style.foreground!=s.foreground||style.border!=s.border;
 if(visualChanged)rendered=false;style=s;width=w;height=h;interactive=touchEnabled;auto c=api.context;if(visualChanged){api.color(c,frame,s.border,false);api.color(c,divider,s.border,false);api.color(c,panel,s.background,false);api.color(c,heading,s.foreground,true);api.color(c,summaryHeading,s.foreground,true);api.color(c,caption,s.foreground,true);}retain();bool ok=redraw();if(alive&&!closed)api.visible(c,root,ok);drop();return ok;
}
DrivePopupView*DrivePopupView::create(ViewApi a,StockProfile s,SignalProfile g,void*contextObject,void*parent,bool(*dispatch)(void*,const DriveAction*,unsigned),bool(*summary)(void*,DriveChoice,DriveSummary&),void*context){
 if(!contextObject||!parent||!dispatch||!summary||!a.create||!a.destroy||!a.rect||!a.text||!a.color||!a.visible||!a.enabled||!a.opacity||!a.name||!a.layer||!a.listen)return nullptr;auto*v=new(std::nothrow)DrivePopupView(a,s,g);if(!v)return nullptr;v->dispatch=dispatch;v->summary=summary;v->context=context;auto make=[&](Kind k,void*p){return a.create(a.context,k,p);};v->root=make(Kind::Item,parent);if(!v->root){delete v;return nullptr;}
 if(!v->bind(v->root,Event::Destroy,-3)){a.destroy(a.context,v->root);delete v;return nullptr;}auto fail=[&](){v->close();return static_cast<DrivePopupView*>(nullptr);};a.name(a.context,v->root,"PopoverDriveMode_root");a.layer(a.context,v->root,1400,false);
 v->shade=make(Kind::Rectangle,v->root);v->outside=make(Kind::Mouse,v->root);v->frame=make(Kind::Rectangle,v->root);if(!v->shade||!v->outside||!v->frame)return fail();a.color(a.context,v->shade,0,false);a.opacity(a.context,v->shade,.7);v->panel=make(Kind::Rectangle,v->frame);if(!v->panel)return fail();a.layer(a.context,v->panel,0,true);v->divider=make(Kind::Rectangle,v->panel);v->heading=make(Kind::Text,v->panel);v->summaryHeading=make(Kind::Text,v->panel);v->caption=make(Kind::Text,v->panel);if(!v->divider||!v->heading||!v->summaryHeading||!v->caption||!stock_set_number(s,v->caption,"wrapMode",3))return fail();
 for(int i=0;i<8;i++){v->icons[i]=stock_create(s,StockKind::FramedImage,contextObject,v->panel);if(!v->icons[i])return fail();char name[48];std::snprintf(name,sizeof name,"NativeDriveIcon%d",i);a.name(a.context,v->icons[i],name);stock_set_bool(s,v->icons[i],"acceptKeys",false);auto*b=new(std::nothrow)Binding(v,i);if(!b)return fail();v->retain();v->presses[i]=signal_watch(g,v->icons[i],v->root,"pressed()",pressed,b,release);if(!v->presses[i]){release(b);return fail();}}
 for(auto&r:v->rows){r=stock_create(s,StockKind::TextValueRow,contextObject,v->panel);if(!r)return fail();}v->summaryTouch=make(Kind::Mouse,v->panel);if(!v->summaryTouch||!v->bind(v->summaryTouch,Event::Click,-2)||!v->bind(v->outside,Event::Click,-1))return fail();a.visible(a.context,v->root,false);return v;
}
bool DrivePopupView::reopen_display(){if(!alive||closed||!root)return false;retain();model.reopen_after_failure();bool ok=redraw();if(alive&&!closed)api.visible(api.context,root,ok);ok=ok&&alive&&!closed;drop();return ok;}
void DrivePopupView::close(){if(closed)return;closed=true;for(auto&w:presses){signal_unwatch(w);w=nullptr;}if(root){auto*p=root;root=nullptr;alive=false;api.destroy(api.context,p);}drop();}
}
